<?php require_once dirname(__DIR__).'/lib.php';session_start();if(empty($_SESSION['admin']))json_out(['ok'=>false,'message'=>'관리자 로그인이 필요합니다.'],403);try{$id=(int)($_POST['id']??0);$s=db()->prepare('SELECT * FROM contracts WHERE id=?');$s->execute([$id]);$c=$s->fetch();if(!$c||!$c['final_pdf'])throw new RuntimeException('먼저 최종 PDF를 생성하세요.');$url=cfg('base_url').'/download.php?id='.$id.'&key='.hash_hmac('sha256',(string)$id.'|'.$c['document_hash'],(string)cfg('security.app_key'));$msg="[임대차계약 완료] {$c['lessee_name']}님, 서명 완료된 최종 임대차계약서 PDF입니다.\n{$url}\n안전하게 보관해 주세요.";$res=send_sms($c['lessee_phone'],$msg,$c['lessee_name']);sms_log($id,$c['lessee_phone'],$msg,$res);audit($id,'admin','final_pdf_link_sent',['sms_ok'=>$res['ok']??false]);json_out(['ok'=>(bool)($res['ok']??false),'message'=>($res['ok']??false)?'최종 PDF 링크 문자를 발송했습니다.':'문자 발송 설정을 확인하세요. PDF는 정상 저장되었습니다.']);}catch(Throwable $e){json_out(['ok'=>false,'message'=>$e->getMessage()],400);}